'use server';

import { z } from 'zod';

/* =========================
   INPUT
========================= */

const MG30PresetInputSchema = z.object({
  description: z.string(),
});

export type MG30PresetInput = z.infer<typeof MG30PresetInputSchema>;

/* =========================
   PARAMETER SCHEMAS (MG-30 REALI)
========================= */

const NoiseGateParams = z.object({
  sensitivity: z.number().min(0).max(100),
  decay: z.number().min(0).max(100),
});

const TScreamParams = z.object({
  drive: z.number().min(0).max(100),
  tone: z.number().min(0).max(100),
  level: z.number().min(0).max(100),
});

const DigitalDelayParams = z.object({
  level: z.number().min(0).max(100),
  feedback: z.number().min(0).max(100),
  time: z.number().min(0).max(100),
  subdivision: z.enum([
    '1/4',
    '1/8',
    '1/8D',
    '1/4T',
    '1/16',
    '1/8T',
    '1/32',
  ]),
});

const HallReverbParams = z.object({
  decay: z.number().min(0).max(100),
  preDelay: z.number().min(0).max(100),
  liveliness: z.number().min(0).max(100),
  level: z.number().min(0).max(100),
});

const AmpModelEnum = z.enum([
  'clean',
  'plexi100w',
  'jcm800',
  'dual-rect',
  'ac30',
]);

/* =========================
   EFFECT SCHEMA
========================= */

const EffectSchema = z.discriminatedUnion('type', [
  z.object({
    type: z.literal('noise-gate'),
    model: z.literal('gate'),
    enabled: z.boolean(),
    parameters: NoiseGateParams,
  }),
  z.object({
    type: z.literal('overdrive'),
    model: z.literal('tscream'),
    enabled: z.boolean(),
    parameters: TScreamParams,
  }),
  z.object({
    type: z.literal('delay'),
    model: z.literal('digital'),
    enabled: z.boolean(),
    parameters: DigitalDelayParams,
  }),
  z.object({
    type: z.literal('reverb'),
    model: z.literal('hall'),
    enabled: z.boolean(),
    parameters: HallReverbParams,
  }),
]);

const MG30PresetOutputSchema = z.object({
  name: z.string(),
  ampModel: AmpModelEnum,
  effects: z.array(EffectSchema).min(3).max(5),
});

export type MG30PresetOutput = z.infer<typeof MG30PresetOutputSchema>;

/* =========================
   GENERIC PARAMS EXTRACTOR
========================= */

export function extractPresetParameters(preset: MG30PresetOutput) {
  const params: Record<string, any> = {};
  preset.effects.forEach((effect) => {
    params[effect.type] = effect.parameters;
  });
  params.ampModel = preset.ampModel;
  params.name = preset.name;
  return params;
}

/* =========================
   GENERATOR (API Gemini)
========================= */

export async function generateMG30Preset(
  input: MG30PresetInput
): Promise<MG30PresetOutput> {
  const apiKey = process.env.GOOGLE_GENAI_API_KEY;

  if (!apiKey) throw new Error('GOOGLE_GENAI_API_KEY non configurata');

  const response = await fetch(
    `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash-lite:generateContent?key=${apiKey}`,
    {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        contents: [
          {
            parts: [
              {
                text: `Sei un sound designer esperto di NUX MG-30.

DESCRIZIONE SUONO:
"${input.description}"

Genera SOLO JSON valido con questa struttura ESATTA:

{
  "name": "Nome preset",
  "ampModel": "clean | plexi100w | jcm800 | dual-rect | ac30",
  "effects": [
    {
      "type": "noise-gate",
      "model": "gate",
      "enabled": true,
      "parameters": {
        "sensitivity": 0-100,
        "decay": 0-100
      }
    },
    {
      "type": "overdrive",
      "model": "tscream",
      "enabled": true,
      "parameters": {
        "drive": 0-100,
        "tone": 0-100,
        "level": 0-100
      }
    },
    {
      "type": "delay",
      "model": "digital",
      "enabled": true,
      "parameters": {
        "level": 0-100,
        "feedback": 0-100,
        "time": 0-100,
        "subdivision": "1/4 | 1/8 | 1/8D | 1/4T | 1/16 | 1/8T | 1/32"
      }
    },
    {
      "type": "reverb",
      "model": "hall",
      "enabled": true,
      "parameters": {
        "decay": 0-100,
        "preDelay": 0-100,
        "liveliness": 0-100,
        "level": 0-100
      }
    }
  ]
}

REGOLE:
- Solo i parametri indicati
- 0-100
- 3-5 effetti
- Nessun testo fuori dal JSON`,
              },
            ],
          },
        ],
        generationConfig: { temperature: 0.7, maxOutputTokens: 700 },
      }),
    }
  );

  if (!response.ok) throw new Error(`Errore API Gemini ${response.status}`);

  const data = await response.json();
  let text = data.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!text) throw new Error('Risposta vuota da Gemini');

  text = text.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(text);
  return MG30PresetOutputSchema.parse(parsed);
}

